public static class Registry<T> where T : class
{
    private static readonly ConcurrentDictionary<string, Func<T>> Map =
        new ConcurrentDictionary<string, Func<T>>();
    public static void Register(string key, Func<T> factory)
    {
        if (!Map.TryAdd(key, factory))
            throw new InvalidOperationException($"duplicate registration: {key}");
    }
    public static T Resolve(string key) =>
        Map.TryGetValue(key, out var f)
            ? f()
            : throw new KeyNotFoundException($"unknown key: {key}");
}
